import{_ as t,o as a,c as i,an as r}from"./chunks/framework.BjfRDIIO.js";const g=JSON.parse('{"title":"Introduction","description":"","frontmatter":{},"headers":[],"relativePath":"manual/introduction.md","filePath":"manual/introduction.md","lastUpdated":null}'),s={name:"manual/introduction.md"};function l(o,e,n,h,d,p){return a(),i("div",null,[...e[0]||(e[0]=[r(`<h1 id="Introduction" tabindex="-1">Introduction <a class="header-anchor" href="#Introduction" aria-label="Permalink to &quot;Introduction {#Introduction}&quot;">​</a></h1><p>Microclimate modellers want small-scale predictions over large areas, often hourly. That is a lot of computation, and it competes with the need to try new ideas quickly. The answer here is a set of <em>levers</em> that switch between research modes without rewriting anything:</p><ul><li><p><strong>spatial resolution</strong>: the grid a run is solved on;</p></li><li><p><strong>temporal resolution</strong>: monthly, daily or hourly forcing;</p></li><li><p><strong>formulation accuracy</strong>: which equation for each process;</p></li><li><p><strong>formulation completeness</strong>: which processes, such as snow or a canopy, are included.</p></li></ul><p><a href="https://biophysicalecology.github.io/Microclimate.jl/dev" target="_blank" rel="noreferrer">Microclimate.jl</a> solves the microclimate at a point from weather, terrain, soil and vegetation inputs. MicroclimateMapper.jl supplies those inputs from spatial data sets, for one point, many points or every cell of a grid.</p><h2 id="Model-and-problem" tabindex="-1">Model and problem <a class="header-anchor" href="#Model-and-problem" aria-label="Permalink to &quot;Model and problem {#Model-and-problem}&quot;">​</a></h2><p>The packages of <a href="https://github.com/BiophysicalEcology" target="_blank" rel="noreferrer">BiophysicalEcology</a> use two words throughout:</p><ul><li><p>a <strong>model</strong> is a physical specification, without a place or time;</p></li><li><p>a <strong>problem</strong> is a model with a place and time, which can be solved.</p></li></ul><p>A <a href="/MicroclimateMapper.jl/previews/PR39/api#MicroclimateMapper.MicroMapModel"><code>MicroMapModel</code></a> wraps the point model of Microclimate.jl, a <code>MicroModel</code>, with the data sets to drive it: a DEM, a weather source, and optionally land cover, surface properties and soil moisture. It says nothing about where or when. A <a href="/MicroclimateMapper.jl/previews/PR39/api#MicroclimateMapper.MicroVectorProblem"><code>MicroVectorProblem</code></a> pairs it with points and dates; a <a href="/MicroclimateMapper.jl/previews/PR39/api#MicroclimateMapper.MicroRasterProblem"><code>MicroRasterProblem</code></a> with an area, a grid and dates. <code>solve</code> returns a <code>RasterStack</code>.</p><div class="language-julia vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">julia</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">model </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> MicroMapModel</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(; micro_model, dem_source </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> SRTM, weather_source </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> CRUCL2)</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">points </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> MicroVectorProblem</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(; model, points </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [(</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">89.40</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">43.07</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)], dates, soil_profile)</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">grid </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> MicroRasterProblem</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(; model, area, template </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> SRTM, dates, soil_profile)</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">solve</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(points), </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">solve</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(grid)</span></span></code></pre></div><p>The design follows from a few principles:</p><ul><li><p><strong>Declarative</strong>: a script says what to solve, not how.</p></li><li><p><strong>Modular</strong>: data sets and model components are swapped for alternatives with one keyword, see <a href="./data_sources">One keyword per data set</a>.</p></li><li><p><strong>Unit-safe</strong>: every quantity carries its units, which are checked.</p></li><li><p><strong>Readable</strong>: formulations are short and look like the equations they come from.</p></li><li><p><strong>Fast</strong>: Julia can approach the performance of Fortran and C, see <a href="./performance">Performance</a>.</p></li></ul><h2 id="How-it-combines-with-the-Microclimate.jl-package" tabindex="-1">How it combines with the Microclimate.jl package <a class="header-anchor" href="#How-it-combines-with-the-Microclimate.jl-package" aria-label="Permalink to &quot;How it combines with the Microclimate.jl package {#How-it-combines-with-the-Microclimate.jl-package}&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">Step</th><th style="text-align:left;">Done here</th></tr></thead><tbody><tr><td style="text-align:left;">fetching data</td><td style="text-align:left;">data sets as types of <a href="https://ecojulia.github.io/RasterDataSources.jl/stable" target="_blank" rel="noreferrer">RasterDataSources.jl</a>, downloaded once and cached, see <a href="./spatial_stack">Built on Rasters and DimensionalData</a></td></tr><tr><td style="text-align:left;">forcing</td><td style="text-align:left;">each data set&#39;s variables converted to one hourly forcing, whatever its native time step, see <a href="./forcing_data">Forcing data sets</a></td></tr><tr><td style="text-align:left;">terrain</td><td style="text-align:left;">slope, aspect and horizon angles from any DEM, with <a href="https://deltares.github.io/Geomorphometry.jl/stable/" target="_blank" rel="noreferrer">Geomorphometry.jl</a>, and weather corrected for elevation, see <a href="./terrain">Terrain and atmosphere</a></td></tr><tr><td style="text-align:left;">surfaces and soils</td><td style="text-align:left;">albedo and roughness from land cover, soil profiles from texture maps, see <a href="./surfaces_soils">Surfaces and soils</a></td></tr><tr><td style="text-align:left;">running</td><td style="text-align:left;">every point or cell in parallel, with the results gathered into one <code>RasterStack</code>, see <a href="./outputs">Outputs</a></td></tr></tbody></table><p>Microclimate.jl treats each point as part of an infinite uniform plane. Flows between neighbouring cells, such as runoff and cold-air drainage, need the grid and so belong here. Runoff routing is in development, see <a href="./lateral_flows">Lateral flows</a>.</p><h2 id="The-ecosystem" tabindex="-1">The ecosystem <a class="header-anchor" href="#The-ecosystem" aria-label="Permalink to &quot;The ecosystem {#The-ecosystem}&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">Package</th><th style="text-align:left;">Role</th></tr></thead><tbody><tr><td style="text-align:left;"><a href="https://biophysicalecology.github.io/Microclimate.jl/dev" target="_blank" rel="noreferrer">Microclimate.jl</a></td><td style="text-align:left;">the microclimate at a point</td></tr><tr><td style="text-align:left;"><a href="https://biophysicalecology.github.io/SolarRadiation.jl/dev" target="_blank" rel="noreferrer">SolarRadiation.jl</a></td><td style="text-align:left;">clear-sky solar radiation over terrain</td></tr><tr><td style="text-align:left;"><a href="https://biophysicalecology.github.io/FluidProperties.jl/stable/" target="_blank" rel="noreferrer">FluidProperties.jl</a></td><td style="text-align:left;">properties of air and water</td></tr><tr><td style="text-align:left;"><a href="https://biophysicalecology.github.io/HeatExchange.jl/dev" target="_blank" rel="noreferrer">HeatExchange.jl</a></td><td style="text-align:left;">heat and water budgets of organisms in these microclimates</td></tr><tr><td style="text-align:left;"><a href="https://biophysicalecology.github.io/BiophysicalBehaviour.jl/dev" target="_blank" rel="noreferrer">BiophysicalBehaviour.jl</a></td><td style="text-align:left;">organisms choosing among these microclimates, see <a href="https://biophysicalecology.github.io/BiophysicalBehaviour.jl/dev/manual/environments#From-gridded-climate-data" target="_blank" rel="noreferrer">Activity and available environments</a></td></tr><tr><td style="text-align:left;"><a href="https://ecojulia.github.io/RasterDataSources.jl/stable" target="_blank" rel="noreferrer">RasterDataSources.jl</a>, <a href="https://rafaqz.github.io/Rasters.jl/stable" target="_blank" rel="noreferrer">Rasters.jl</a>, <a href="https://rafaqz.github.io/DimensionalData.jl/stable/" target="_blank" rel="noreferrer">DimensionalData.jl</a>, <a href="https://deltares.github.io/Geomorphometry.jl/stable/" target="_blank" rel="noreferrer">Geomorphometry.jl</a>, <a href="https://github.com/BiophysicalEcology/PointDataSources.jl" target="_blank" rel="noreferrer">PointDataSources.jl</a></td><td style="text-align:left;">fetching, holding and analysing the spatial data</td></tr></tbody></table><p>MicroclimateMapper.jl is the Julia counterpart of the <code>micro_global</code>, <code>micro_usa</code>, <code>micro_ncep</code> and related functions of <a href="https://github.com/mrke/NicheMapR" target="_blank" rel="noreferrer">NicheMapR</a> (Kearney and Porter 2017), see <a href="./nichemapr">For NicheMapR users</a>.</p>`,17)])])}const f=t(s,[["render",l]]);export{g as __pageData,f as default};
